import {info} from '/help.js';
import * as LP from '/local-projects.js';
import {executionUI} from '/execution.js';
import {researchDesk} from '/desk.js';
import * as store from '/store.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialRoute=new URLSearchParams(location.hash.slice(1));
const methodScopes=new Map();
let samples=[],removed=LP.readRemoved(localStorage);
let screen=initialRoute.get('screen')||(!location.hash?'desk':'project');
let token='',projects=[],active=initialRoute.get('screen')==='new'?null:(initialRoute.get('id')||localStorage.getItem('research-project')),tab=initialRoute.get('view')||'compare',selected=new Set(),provider=localStorage.getItem('relay-provider'),model=localStorage.getItem('relay-model'),signature='',dirty=false,editorFile='tex',zoom=1,expandedTopics=new Set(),pairFilter='all',pairDisplayLimit=25,pairQuery='',comparisonCache={key:'',data:null};
const BUSY=['discovering','drafting','investigating'];
let serverKeys={},hostedMode=false;
const cleanKey=v=>String(v||'').replace(/[^\x21-\x7E]/g,'');
const keyFor=p=>cleanKey(sessionStorage.getItem('relay-key-'+p));
function keyHeaders(p=provider,path='research'){const h={},k=keyFor(p);if(k){h['X-Provider-Key']=k;h['X-Provider']=p}const t=keyFor('tavily');if(t&&path.startsWith('research'))h['X-Tavily-Key']=t;return h}
const current=()=>projects.find(p=>p.id===active), busy=p=>BUSY.includes(p.status);
const FIELD_LABELS={method:'Method / intervention',entityId:'Entity assignment',outcomeId:'Requested outcome',outcomeQuote:'Outcome membership evidence',entityQuote:'Entity membership evidence',measurementQuote:'Measurement evidence',dataset:'Dataset',datasetVersion:'Dataset version',split:'Evaluation partition / split',factor_distillation:'Distillation eligibility',horizon:'Forecast horizon',aggregation:'Aggregation',preprocessing:'Preprocessing',metricDefinition:'Metric definition',provenance:'Provenance',citedFrom:'Cited from',locator:'Source location',name:'Metric',value:'Value',unit:'Unit',direction:'Direction'};
const CONTEXT=['method','dataset','datasetVersion','split','horizon','aggregation','preprocessing','metricDefinition','provenance','citedFrom','locator'];
function factors(m){return m?.protocol?.factors||[]}
function contextFields(m){if(m.protocol?.version===3)return ['method','entityId','entityQuote','measurementQuote','outcomeId','outcomeQuote','provenance','locator',...factors(m).map(f=>f.key)];return [...CONTEXT.filter(k=>k!=='horizon'||!m.protocol?.task||m.protocol.task==='forecasting'),...factors(m).map(f=>f.key)]}
function visibleFactors(m){if(m.protocol?.version===3)return factors(m);return factors(m).filter(f=>!(/evaluation partition|train.*val.*split|dataset split|eval.*split|validation split/i.test(f.key.replaceAll('_',' ')+' '+f.label)))}
function fieldLabel(k,m){return factors(m).find(f=>f.key===k)?.label||FIELD_LABELS[k]||k.replace(/^factor_/, '').replaceAll('_',' ')}
function protocolPanel(p){if(!p.protocol)return '<div class="notice">This saved evidence needs a question coverage plan. Branch and re-extract to create one.</div>';const c=p.protocol,complete=c.planReview?.complete,reviewed=p.contractReview?.approved;return `<details class="notice" ${complete?'':'open'}><summary>Question coverage · ${reviewed?'Human reviewed':complete?'Ready for human review':'Requirements unresolved'}</summary><p>${esc(c.task)}</p><div class="entity-contract">${(c.entities||[]).map(e=>`<article><strong>${esc(e.label)}</strong><p>${esc(e.definition)}</p></article>`).join('')}</div><div class="requirements-list">${(c.requirements||[]).map(r=>`<article><strong>${r.covered?'✓':'?'} ${esc(r.quote)}</strong><p>${esc(r.interpretation)}</p><small>${esc(r.role)} · ${esc((r.criteria||[]).join(', '))}</small></article>`).join('')||'<p>The question requirements have not been audited in this saved run.</p>'}</div>${(c.goals||[]).length?`<h3>Questions this investigation must answer</h3>${c.goals.map(g=>`<article><strong>${esc(g.questionQuote)}</strong><p>${esc(g.decisionRule)}</p></article>`).join('')}`:''}${(c.planReview?.gaps||[]).map(g=>`<p class="warn">${esc(g)}</p>`).join('')}<div class="meta">${(c.factors||[]).map(f=>`<span class="badge" title="${esc(f.rule||f.reason)}">${esc(f.label)} · ${esc(f.role)}</span>`).join('')}</div><div class="entity-contract">${(c.outcomes||[]).map(o=>`<article><strong>Requested outcome: ${esc(o.label)}</strong><p>${esc(o.definition)}</p></article>`).join('')}</div><p>Match requires aligned conditions. Stratify requires known categories on both sides. Optional context does not settle the hypothesis.</p><div class="actions"><button id="revise-criteria">Revise question coverage in a branch →</button>${complete?`<button id="review-contract" ${busy(p)?'disabled':''}>${reviewed?'Edit coverage review':'Review question coverage'}</button>`:''}</div></details>`}
function coveragePanel(p){const rows=p.papers||[],withResults=rows.filter(x=>x.metrics.length).length;return `<section class="coverage-panel"><span class="kicker">EVIDENCE COVERAGE</span><h3>${withResults} of ${rows.length} papers contributed retained results</h3><p>Retrieved text, model reading, and scientific completeness are different. Zero extracted results does not mean a paper has no results.</p><div class="coverage-list">${rows.map(x=>{const c=x.coverage;return `<article><button data-coverage-paper="${esc(x.id)}">${esc(x.title)}</button><div class="meta"><span>${esc(x.evidenceKind||'Source unknown')}</span><strong>${x.metrics.length} retained observations</strong><span>${x.metrics.filter(m=>m.outcomeId==='outside_scope').length} outside requested outcomes · ${x.metrics.filter(m=>m.protocol?.outcomes?.length&&(!m.outcomeId||m.outcomeId==='unknown')).length} awaiting outcome classification</span>${c?`<span>${c.readPassages}/${c.totalPassages} passages read</span><span>${c.returned||0} returned · ${c.rejected||0} rejected attempts</span><span>${Number(c.tokens||0).toLocaleString()} tokens</span>`:'<span>Coverage was not recorded in this saved run</span>'}</div>${c?`<progress value="${c.coveredChars||0}" max="${c.sourceChars||1}" aria-label="Retrieved source coverage"></progress><p>${esc(c.stopReason||c.status)}</p>`:''}</article>`}).join('')}</div></section>`}
function bindCoverage(){document.querySelectorAll('[data-coverage-paper]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.coveragePaper))}

const SUPPORT={quoted:['Quoted','In the result quote or a field quote'],nearby:['Near result','Found near the result in the source'],document:['In paper','Found elsewhere in the paper'],derived:['Derived','Derived from the table column'],repository:['Code','From the authors’ repository, accepted by you'],researcher:['You','Your correction'],default:['Default','Paper’s own method'],missing:['Unresolved','Not yet supported by inspected evidence'],unsupported:['Rejected','The model claimed a value that is not in the source']};
const OUTCOME={pending:['Awaiting assessment','No current model judgment'],comparable:['Comparable within scope','Required context resolved'],incompatible:['Incompatible','The settings differ'],insufficient:['Insufficient evidence','Required evidence unresolved']};
const known=v=>!['','unknown','not reported','not stated','n/a','none','null'].includes(String(v??'').trim().toLowerCase());
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{...(data?{'Content-Type':'application/json','Authorization':'Bearer '+token}:{}),...keyHeaders((path.match(/provider=(\w+)/)||[])[1]||provider,path)},body:data?JSON.stringify(data):undefined});const x=await r.json();if(!r.ok)throw Error(x.error||'Request failed');return x;}
function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').hidden=true,6000)}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
$('.close').onclick=()=>$('#dialog').close();
async function refresh(force=false){try{await loadProjects();local.down=false;try{samples=(await api('research/samples')).projects}catch{}await dropSampleCopies();await restoreMissing();syncCopies();const sig=JSON.stringify(projects);sidebar();if((force||sig!==signature)&&!dirty){signature=sig;const y=window.scrollY;render();requestAnimationFrame(()=>window.scrollTo(0,y))}}catch(e){if(isNetworkError(e)){local.down=true;sidebar();return}toast(e.message)}}
async function beforeNavigate(){if(!dirty)return true;try{await saveEditor();return true}catch(e){toast(e.message);return false}}
function routeTo(node){const q=new URLSearchParams();if(['history','desk'].includes(screen))q.set('screen',screen);else if(active){q.set('id',active);q.set('view',tab);if(node)q.set('node',node)}else q.set('screen','new');window.history.pushState({},'',location.pathname+'#'+q.toString())}
async function openProject(id,view='compare',node){if(!await beforeNavigate())return;if(!projects.some(p=>p.id===id))await loadProjects([id]);active=id;screen='project';tab=view;localStorage.setItem('research-project',id);selected.clear();if(node)executions.setNode(node);routeTo(node);render();sidebar()}
async function openTab(view){if(!await beforeNavigate())return;tab=view;routeTo();render()}
async function showHistory(){if(!await beforeNavigate())return;screen='history';routeTo();render();sidebar()}
function sidebar(){const have=new Set(projects.map(p=>p.id));const notes=[];if(local.down)notes.push(`<p class="side-note warn">Relay's server is not responding. Your saved projects are still here; try again in a moment.</p>`);if(local.restored)notes.push('<button class="side-note ok" id="dismiss-restored">Restored from your browser copy after the server restarted.</button>');const waiting=local.copies.filter(c=>!have.has(c.id)).map(c=>`<div class="project-link unrestored">${esc(c.hypothesis.slice(0,90))}<small>${esc(local.errors.get(c.id)||(local.down?'Waiting for the server.':'Restoring from your browser copy…'))}</small></div>`);if(!projects.length&&!waiting.length)notes.push(`<p class="side-note">${local.ready?'Start an investigation. It is saved in this browser.':'Start an investigation. This browser window cannot keep it after you close the window.'}</p>`);$('#projects').innerHTML=notes.join('')+projects.filter(p=>!LP.isSample(p)&&!removed.has(p.id)&&(copyOf(p.id)||p.id===active)).map(p=>`<button class="project-link ${p.id===active&&screen==='project'?'active':''}" data-project="${p.id}">${p.parentProject?'⑂ ':''}${esc((p.branchName||p.hypothesis).slice(0,90))}<small>${p.papers.length} papers · ${esc(p.status)} · ${(p.proposals||[]).filter(x=>x.status==='pending').length} proposals</small></button>`).join('');$('#projects').insertAdjacentHTML('beforeend',waiting.join(''));renderSamples();document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.project));if($('#dismiss-restored'))$('#dismiss-restored').onclick=()=>{local.restored=false;sidebar()};$('#model-button').textContent=(model||'Choose model')+' ⌄';$('#executions').classList.toggle('active',screen==='history');$('#desk-nav').classList.toggle('active',screen==='desk')}
$('#executions').onclick=showHistory;
$('#desk-nav').onclick=async()=>{if(!await beforeNavigate())return;screen='desk';routeTo();sidebar();render()};
const closeNavigation=()=>{document.body.classList.remove('nav-open');$('#nav-toggle').setAttribute('aria-expanded','false')};
$('#nav-toggle').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('#nav-toggle').setAttribute('aria-expanded',String(open))};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavigation()});
document.querySelector('main').addEventListener('click',e=>{if(!e.target.closest('#nav-toggle'))closeNavigation()});
async function newInvestigation(){if(!await beforeNavigate())return;active=null;screen='project';tab='compare';localStorage.removeItem('research-project');routeTo();render();sidebar()}
$('#new').onclick=newInvestigation;
window.addEventListener('popstate',async()=>{if(!await beforeNavigate())return;const r=new URLSearchParams(location.hash.slice(1));screen=['history','desk'].includes(r.get('screen'))?r.get('screen'):'project';active=r.get('id');tab=r.get('view')||'compare';if(r.get('node'))executions.setNode(r.get('node'));render();sidebar()});

const TABS=[['map','Question & papers'],['papers','Evidence'],['compare','Comparisons'],['corrections','Corrections'],['write','Experiment & manuscript'],['execution','Execution record']];
function render(){closeNavigation();if(screen==='desk'){$('#crumb').textContent='Research desk';desk.render();return}if(screen==='history'){$('#crumb').textContent='Executions & branches';executions.history();return}const p=current();$('#crumb').textContent=p?'Investigation':'New investigation';if(!p){home();return}
  const pending=(p.proposals||[]).filter(x=>x.status==='pending').length,stale=(p.corrections||[]).filter(c=>c.status==='stale').length;
  const counts={compare:pending?`<span class="tab-count">${pending}</span>`:'',corrections:stale?`<span class="tab-count warn">${stale}</span>`:''};
  $('#main').innerHTML=`<div class="project-head"><div class="kicker">INVESTIGATION / ${esc(p.created.slice(0,10))}${p.branchName?' / ⑂ '+esc(p.branchName):''}</div><h2>${esc(p.hypothesis)}</h2><div class="meta"><span class="badge ${busy(p)?'orange':''}">${busy(p)?'<i class="progress-dot"></i>':''}${esc(p.status==='review'?'Ready for human review':p.status==='needs_scope'?'Question scope needs review':p.status)}</span><span>${p.papers.length} papers</span><span>${p.papers.reduce((n,x)=>n+x.metrics.length,0)} results</span><span>${esc(p.model.includes('nemotron')?'Nemotron · '+p.model:p.model)} · ${p.tokens.toLocaleString()} tokens</span></div>${p.archive?'<p class="agent-review-banner">Recorded study · Ready for human review</p>':''}${busy(p)?`<div class="live-step"><i class="progress-dot"></i>${esc(p.activeStep||'Working…')}${p.activeCall?`<small> · ${esc(p.activeCall.kind)} · model request running</small>`:''}</div>`:''}<nav class="tabs journey" aria-label="Investigation steps">${TABS.map(([id,label],i)=>`<button data-tab="${id}" aria-current="${tab===id?'page':'false'}" class="${tab===id?'active':''}"><span class="tab-index">${i+1}</span>${label}${counts[id]||''}</button>`).join('')}</nav></div><div class="workspace">${p.error?`<div class="notice error">${esc(p.error)}</div>`:''}<div class="view-guide">About this step ${info(tab)}</div><div id="view"></div></div>`;
  document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openTab(b.dataset.tab));
  ({execution:executionView,map:mapView,papers:papersView,compare:compareView,corrections:correctionsView,write:writeView}[tab]||compareView)(p)}

function workloadControl(id,label,initial=10){const custom=![6,10,12,25,'all'].includes(initial);return `<label class="workload-control">${label}<select id="${id}"><option value="6" ${initial===6?'selected':''}>6</option><option value="10" ${initial===10?'selected':''}>10</option><option value="12" ${initial===12?'selected':''}>12</option><option value="25" ${initial===25?'selected':''}>25</option><option value="all" ${initial==='all'?'selected':''}>All available</option><option value="custom" ${custom?'selected':''}>Custom count…</option></select><input id="${id}-custom" type="number" min="1" step="1" value="${custom?initial:20}" aria-label="Custom ${label}" ${custom?'':'hidden'}></label>`}
function bindWorkload(id){$('#'+id).onchange=()=>{$('#'+id+'-custom').hidden=$('#'+id).value!=='custom'}}
function workloadValue(id){const v=$('#'+id).value;if(v==='all')return 'all';const n=Number(v==='custom'?$('#'+id+'-custom').value:v);if(!Number.isSafeInteger(n)||n<1)throw new Error('Enter a positive whole number.');return n}
function home(){$('#main').innerHTML=`<div class="landing"><div class="hero-intro"><div class="kicker"><span class="signal"></span> CHECK THE COMPARISON BEFORE YOU BUILD ON IT</div><h1>Does that research<br><em>comparison hold?</em></h1><p>Relay investigates published results, exposes missing experimental context,<br>and helps you design the next defensible experiment.</p></div><div class="launch-grid"><div class="launch-main"><form class="hypothesis-box" id="search"><div class="question-heading"><span class="step-label">01 / THE QUESTION</span><span class="private-label">Saved locally</span></div><label for="hypothesis">What comparison do you need to trust?</label>${info('question')}<textarea id="hypothesis" required minlength="10" maxlength="2000" placeholder="What claim do you want to investigate, and under which conditions?"></textarea><div class="count-row"><span id="hyp-count" aria-live="polite">0 / 2000</span></div><details class="seed-details"><summary><span>Add papers you are considering</span><small>optional · DOIs, arXiv IDs or links</small></summary><textarea id="seeds" class="seed-box" aria-label="DOIs, arXiv IDs or links, one per line" placeholder="Paste DOI or arXiv references, one per line"></textarea><label class="switch-row"><input type="checkbox" id="seed-only" role="switch"><span class="switch-text"><b>Only analyze these papers</b><small>Skip the literature search and use just the papers above.</small></span></label></details><details class="workload-settings"><summary>Research scope · choose your workload</summary><div class="workload-grid">${workloadControl('paper-budget','Papers to analyze',12)}${workloadControl('result-budget','Results per paper',10)}${workloadControl('comparison-budget','Initial comparisons',12)}</div><p class="hint">All papers uses the initial search set (up to 200 index candidates per query); custom paper counts fetch additional pages. All results uses supplied evidence, not the entire literature. Larger runs take more time and tokens. Model context and response limits still apply; they are not guarantees of exhaustive extraction.</p></details><div class="search-bottom"><span>Public papers and author code · source-checked evidence<br>Your question and retrieved text go to the model you choose.</span><button class="accent" id="discover">Start investigation <span aria-hidden="true">↗</span></button></div></form><div class="home-history"><span>Pick up where you left off.</span><button id="home-history">Browse executions & branches →</button></div></div><div class="feature-grid" aria-label="Research workflow"><div class="feature"><span class="feature-icon" aria-hidden="true">⌘</span><div><span class="number">01 / EVIDENCE</span><h3>Every number keeps its context.</h3><p>The studied entities, outcome definitions, experimental conditions, source quotes, and unresolved assumptions.</p></div></div><div class="feature"><span class="feature-icon" aria-hidden="true">⇄</span><div><span class="number">02 / COMPARE</span><h3>Comparable, incompatible, or unknown.</h3><p>Missing context is never treated as proof of a mismatch. The agent goes looking for it.</p></div></div><div class="feature"><span class="feature-icon" aria-hidden="true">↻</span><div><span class="number">03 / CORRECT</span><h3>Corrections propagate.</h3><p>See which comparisons and manuscript claims change, regenerate them after review, and keep the old state as a branch.</p></div></div></div></div></div>`;
  ['paper-budget','result-budget','comparison-budget'].forEach(bindWorkload);$('#home-history').onclick=showHistory;const hypCount=()=>{const n=$('#hypothesis').value.length;$('#hyp-count').textContent=n+' / 2000';$('#hyp-count').classList.toggle('near',n>1800)};$('#hypothesis').oninput=hypCount;hypCount();
  $('#search').onsubmit=async e=>{e.preventDefault();if(!serverKeys[provider]&&!keyFor(provider)){toast('Add your API key first: open the model menu and paste it.');$('#model-button').click();return}const b=$('#discover');b.disabled=true;b.textContent='Starting…';try{const seeds=$('#seeds').value.split(/[\s,]+/).filter(Boolean);const r=await api('research/start',{hypothesis:$('#hypothesis').value,provider,model,seeds,seedOnly:$('#seed-only').checked,paperLimit:workloadValue('paper-budget'),resultLimit:workloadValue('result-budget'),comparisonLimit:workloadValue('comparison-budget')});active=r.id;saveCopy(r.id);selected.clear();tab='compare';screen='project';localStorage.setItem('research-project',active);routeTo();await refresh(true)}catch(e){toast(e.message);b.disabled=false;b.textContent='Start investigation ↗'}}}

function events(p){return `<div class="activity">${p.events.slice(-7).map(e=>`<div>${esc(e.message)}</div>`).join('')||'Agent preparing…'}</div>`}
function tray(p){return `<div class="compare-tray" id="tray"><div class="tray-label">＋ Focus comparisons<small>Drag papers here to limit comparisons to them</small></div>${p.papers.filter(x=>selected.has(x.id)).map(x=>`<div class="chip"><span>${esc(x.title)}</span><button data-remove="${x.id}" aria-label="Remove ${esc(x.title)}">×</button></div>`).join('')}<button class="primary" id="compare-now">${selected.size>=2?`Compare ${selected.size} papers →`:'Compare all papers →'}</button></div>`}
function bindTray(p){const t=$('#tray');t.ondragover=e=>{e.preventDefault();t.classList.add('over')};t.ondragleave=()=>t.classList.remove('over');t.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(p.papers.some(x=>x.id===id))selected.add(id);mapView(p)};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{selected.delete(b.dataset.remove);mapView(p)});$('#compare-now').onclick=()=>openTab('compare')}
function mapView(p){const groups={};for(const paper of p.papers)(groups[paper.topic||'Awaiting assessment']??=[]).push(paper);let y=45,nodes='',edges='',centers=[];const edge=(x1,y1,x2,y2)=>`<path d="M${x1},${y1} C${(x1+x2)/2},${y1} ${(x1+x2)/2},${y2} ${x2},${y2}"/>`;
for(const [topic,allPapers] of Object.entries(groups)){const papers=expandedTopics.has(topic)?allPapers:allPapers.slice(0,1);const start=y;for(const paper of papers){const shown=paper.metrics.slice(0,4),metricH=Math.max(145,shown.length*95);nodes+=`<button class="node paper" data-paper="${paper.id}" style="left:505px;top:${y}px"><small>${paper.year||'—'} · ${esc(paper.venue?.slice(0,30)||'Scholarly paper')} ${paper.reviewed?'· ✓':''}</small><strong>${esc(paper.title)}</strong><div class="node-foot"><span>${paper.metrics.length} results · ${esc(paper.sourceRef?'Full text':'Abstract')}</span><span>${paper.relevance??'…'}/100 fit</span></div></button>`;shown.forEach((m,i)=>{nodes+=`<button class="node metric" data-metric-paper="${paper.id}" style="left:810px;top:${y+i*95}px"><small>${esc(m.dataset)} · ${esc(m.horizon)}</small><strong>${esc(m.method)} · ${esc(m.name)} ${esc(m.value)} ${m.verified?'✓':''}</strong></button>`;edges+=edge(759,y+60,810,y+i*95+35)});y+=metricH+20}const cy=start+65;centers.push(cy);nodes+=`<button class="node topic" data-topic="${esc(topic)}" style="left:275px;top:${cy-40}px"><small>${allPapers.length} PAPERS · ${expandedTopics.has(topic)?'COLLAPSE −':'EXPAND +'}</small><strong>${esc(topic)}</strong></button>`;let py=start;for(const paper of papers){edges+=edge(455,cy,505,py+60);py+=Math.max(145,paper.metrics.slice(0,4).length*95)+20}y+=35}
const rootY=160;nodes+=`<div class="node root" style="left:30px;top:${rootY-70}px"><small>YOUR QUESTION</small><strong>${esc(p.hypothesis)}</strong></div>`;for(const cy of centers)edges+=edge(230,rootY,275,cy);
$('#view').innerHTML=`<div class="toolbar"><small>Click a paper to open its evidence · expand a topic · drag papers into the tray to focus comparisons</small><div><button id="add-paper">＋ Add paper by DOI / arXiv</button> <button id="zoom-out" aria-label="Zoom out">−</button> <button id="zoom-reset">${Math.round(zoom*100)}%</button> <button id="zoom-in" aria-label="Zoom in">＋</button></div></div><div class="map-layout"><div><div class="map-shell"><div class="map-scroll"><div class="map-canvas" style="width:${1040*zoom}px;height:${Math.max(y,500)*zoom}px"><div id="map-inner" style="width:1040px;height:${Math.max(y,500)}px;transform:scale(${zoom});transform-origin:0 0"><svg width="1040" height="${Math.max(y,500)}">${edges}</svg>${nodes}</div></div></div><div class="map-legend"><span>● Question &nbsp; ◌ Method family &nbsp; □ Paper &nbsp; ◇ Result</span><span>Fit = model relevance estimate</span></div></div>${tray(p)}</div><aside class="map-side"><div class="side-card"><h3>${busy(p)?'<i class="progress-dot"></i>':''} Research agent</h3>${events(p)}</div><div class="side-card"><h3>Where to go next ↗</h3>${p.suggestions.length?p.suggestions.map((s,i)=>`<div class="suggestion"><strong>${esc(s.topic)}</strong><p>Suggested question, not a verified gap in the literature.</p><small>Linked evidence: ${esc((s.paperIds||[]).join(', '))}</small><br><button data-explore="${i}">Explore question ↗</button></div>`).join(''):'<p>Related questions appear after the agent assesses the papers.</p>'}</div></aside></div>${p.synthesis?`<div class="side-card"><h3>Working assessment <span class="badge">${p.synthesisStale?'Earlier assessment · evidence changed':'Unreviewed model interpretation'}</span></h3><p>${esc(p.synthesis)}</p></div>`:''}`;
document.querySelectorAll('[data-paper]').forEach(b=>{b.onclick=()=>{if(b.dataset.dragged==='1'){delete b.dataset.dragged;return}paperDetail(b.dataset.paper)};b.onkeydown=e=>{if(e.key==='Enter')paperDetail(b.dataset.paper)};b.onpointerdown=e=>{if(e.button!==0)return;const start={x:e.clientX,y:e.clientY};let moved=false;b.setPointerCapture(e.pointerId);b.onpointermove=ev=>{if(Math.hypot(ev.clientX-start.x,ev.clientY-start.y)>8){moved=true;b.classList.add('dragging');const r=$('#tray').getBoundingClientRect();$('#tray').classList.toggle('over',ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom)}};b.onpointerup=ev=>{b.onpointermove=null;b.classList.remove('dragging');if(moved)b.dataset.dragged='1';const r=$('#tray').getBoundingClientRect();$('#tray').classList.remove('over');if(moved&&ev.clientX>=r.left&&ev.clientX<=r.right&&ev.clientY>=r.top&&ev.clientY<=r.bottom){selected.add(b.dataset.paper);mapView(p);toast('Paper added to the comparison focus.')}}}});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{expandedTopics.has(b.dataset.topic)?expandedTopics.delete(b.dataset.topic):expandedTopics.add(b.dataset.topic);mapView(p)});document.querySelectorAll('[data-metric-paper]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.metricPaper));bindTray(p);$('#zoom-out').onclick=()=>{zoom=Math.max(.45,zoom-.15);mapView(p)};$('#zoom-in').onclick=()=>{zoom=Math.min(1.6,zoom+.15);mapView(p)};$('#zoom-reset').onclick=()=>{zoom=1;mapView(p)};$('#add-paper').onclick=()=>addPaperDialog(p);document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>{const q=p.suggestions[+b.dataset.explore].topic;active=null;home();$('#hypothesis').value=q})}
function addPaperDialog(p){modal(`<div class="kicker">ADD A PAPER</div><h2>Add a paper you are considering.</h2><p>Relay retrieves its arXiv full text, extracts results with their context, and adds them to the comparisons.</p><label>arXiv ID or link<input type="text" id="arxiv-id" placeholder="2101.06861"></label><button class="primary" id="add-go" ${busy(p)?'disabled':''}>Add and extract</button>`);$('#add-go').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'add-paper',arxiv:$('#arxiv-id').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}}}

function missingCount(x){return x.metrics.reduce((n,m)=>n+(m.missing||[]).length,0)}
function papersView(p){$('#view').innerHTML=`<div class="toolbar"><small>Each result keeps its experimental context. Missing fields are shown, not guessed.</small><span><button id="add-paper">＋ Add paper by DOI / arXiv</button> <span class="badge">${p.papers.length} real records</span></span></div><div class="paper-list">${p.papers.map(x=>{const cellOk=x.metrics.filter(m=>m.checks?.cell?.ok).length;return `<article class="paper-card"><span class="score">${x.relevance??'…'}/100 fit</span><span class="badge">${x.year||'—'} ${x.reviewed?(x.reviewActor==='agent'?'· Agent reviewed':'· Reviewed'):''} ${x.origin==='researcher'?'· Your paper':''}</span><h3><button class="title-open" data-inspect="${x.id}">${esc(x.title)}</button></h3><p>${esc(x.rationale||'Assessment in progress…')}</p><div class="evidence-stats"><span><b>${x.metrics.length}</b> results</span><span><b>${cellOk}</b> table cells matched</span><span class="${missingCount(x)?'warn':''}"><b>${missingCount(x)}</b> context gaps</span><span><b>${x.metrics.filter(m=>m.verified).length}</b> verified</span></div><p class="source-kind">${esc(x.evidenceKind)}</p><div class="paper-actions"><button data-inspect="${x.id}">Open evidence ↗</button>${x.url?`<a class="paper-link" href="${esc(x.url)}" target="_blank" rel="noopener">Original paper ↗</a>`:''}<button data-add="${x.id}">${selected.has(x.id)?'✓ In focus':'+ Focus'}</button></div></article>`}).join('')}</div>`;document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.inspect));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{selected.add(b.dataset.add);b.textContent='✓ In focus'});$('#add-paper').onclick=()=>addPaperDialog(p)}

function supportChip(status){const s=SUPPORT[status]||[status||'—',''];return `<span class="support support-${esc(status||'none')}" title="${esc(s[1])}">${esc(s[0])}</span>`}
function evidenceCard(p,x,m,i){const cell=m.checks?.cell,support=m.checks?.support||{};const rejected=Object.entries(m.rejected||{});return `<div class="metric-entry evidence-card"><div class="evidence-head"><h3>${esc(m.method)} · ${esc(m.name)} = ${esc(m.value)} ${known(m.unit)?esc(m.unit):''}</h3><span class="badge">${esc(m.provenance==='own'?'Authors’ own-method result':m.provenance==='cited'?'Cited from another paper':m.provenance==='reproduced'?'Baseline re-run by paper’s authors':'Provenance unknown')}</span></div>${cell?`<div class="cell-check ${cell.ok?'ok':'warn'}">${cell.ok?'✓':'!'} Table cell: <b>${esc(cell.path)}</b>${cell.caption?` <span>· ${esc(cell.caption.slice(0,110))}</span>`:''}${cell.ok?'':' — the row/column labels do not name this model and metric; check the table.'}</div>`:'<div class="cell-check">Not located in a table. Check the quoted sentence.</div>'}<dl class="metric-grid context-grid">${['name','value','unit','direction',...contextFields(m)].map(k=>{const ev=m.evidence?.[k];return `<div class="${(m.missing||[]).includes(k)?'gap':''}"><dt><label for="metric-${i}-${k}">${esc(fieldLabel(k,m))}</label>${info(k==='provenance'?'provenance':'context')}${support[k]?supportChip(support[k])+info('support'):''}</dt><dd>${['entityId','outcomeId'].includes(k)?`<select id="metric-${i}-${k}" data-edit-metric="${i}" data-field="${k}"><option value="unknown">Unresolved membership</option>${(k==='entityId'?(m.protocol.entities||[]):[...(m.protocol.outcomes||[]),{id:'outside_scope',label:'Outside requested outcome scope'}]).map(e=>`<option value="${esc(e.id)}" ${m[k]===e.id?'selected':''}>${esc(e.label)}</option>`).join('')}</select>`:`<input type="text" id="metric-${i}-${k}" data-edit-metric="${i}" data-field="${k}" value="${esc(m[k])}">`}${ev?.quote?`<details><summary>${esc(ev.origin==='repository'?'Code evidence':ev.origin==='researcher'?'Your note':'Source quote')}</summary><q>${esc(ev.quote)}</q>${ev.location?`<small>${esc(ev.location)}</small>`:''}</details>`:''}</dd></div>`}).join('')}</dl><blockquote>${esc(m.quote)}${m.quoteLocated?'<small> · row located by Relay from the table cell</small>':''}</blockquote>${(m.sourceEvidence||[]).length?`<details><summary>Source rows and headers</summary>${m.sourceEvidence.map(e=>`<blockquote><small>${esc(e.line)}</small>${esc(e.quote)}</blockquote>`).join('')}</details>`:''}${rejected.length?`<div class="rejected"><b>Model claims removed by source checks:</b> ${rejected.map(([k,v])=>`${esc(FIELD_LABELS[k]||k)} “${esc(String(v.value).slice(0,80))}” (${esc(v.reason)})`).join('; ')}</div>`:''}${(m.history||[]).length?`<details class="history"><summary>${m.history.length} correction${m.history.length>1?'s':''}</summary>${m.history.map(h=>`<div>${esc(FIELD_LABELS[h.field]||h.field)}: “${esc(h.before)}” → “${esc(h.after)}” <small>${esc(h.origin)} · ${esc(h.at.slice(0,16).replace('T',' '))}</small></div>`).join('')}</details>`:''}<div class="actions"><label><input type="checkbox" class="verify" value="${i}" ${m.verified?'checked':''}> I checked this value and its context against the source.</label>${info('review')}${(m.missing||[]).length?`<button data-investigate-metric="${m.id}" ${busy(p)?'disabled':''}>Investigate ${m.missing.length} gap${m.missing.length>1?'s':''} with agent</button>`:''}</div></div>`}
function paperDetail(id){const p=current(),x=p.papers.find(x=>x.id===id);if(!x)return;modal(`<div class="kicker">PAPER / EXPERIMENTAL EVIDENCE</div><h2>${esc(x.title)}</h2><p>${esc(x.authors.join(', '))} · ${x.year||'—'}<br>${esc(x.venue)} · ${x.citations} citations</p><a href="${esc(x.url)}" target="_blank" rel="noopener">Open original paper ↗</a> &nbsp; <a href="${esc(x.evidenceUrl)}" target="_blank" rel="noopener">Evidence source ↗</a><div class="notice">${esc(x.evidenceKind)}. Relevance ${x.relevance??'—'}/100 is a model estimate of fit, not scientific quality.${x.rejectedMetrics?` ${x.rejectedMetrics} extracted number(s) were discarded because their quote or value was not in the source.`:''}</div><label>Topic family<input type="text" id="paper-topic" value="${esc(x.topic||'Other approaches')}"></label><label>Hypothesis-fit assessment (editable model interpretation)<textarea id="paper-rationale">${esc(x.rationale)}</textarea></label><details><summary>Read abstract</summary><p>${esc(x.abstract||'No abstract returned by the index.')}</p></details>${x.coverage?`<details open><summary>Extraction coverage · ${esc(x.coverage.status)}</summary><p>${esc(x.coverage.stopReason)}</p><p>${x.coverage.readPassages}/${x.coverage.totalPassages} passages read · ${x.coverage.returned||0} returned · ${x.metrics.length} retained · ${x.coverage.rejected||0} rejected attempts</p>${(x.coverage.failures||[]).map(f=>`<p class="warn">${esc(f.error)}</p>`).join('')}${(x.coverage.contextFailures||[]).map(e=>`<p class="warn">Context completion: ${esc(e)}</p>`).join('')}<p>${x.coverage.contextFieldsFilled||0} context fields filled from source evidence; remaining unknown fields require investigation or review.</p>${(x.rejectionDetails||[]).map(r=>`<details><summary>${esc(r.method)} ${esc(r.value)} · ${esc(r.reason)}</summary><blockquote>${esc(r.quote)}</blockquote></details>`).join('')}</details>`:''}<h3>Reported results ${info('papers')} ${info('provenance')}</h3><p class="hint">Edit a context field to correct it. Relay shows which comparisons and manuscript claims your correction affects. Values must stay inside their quotes.</p>${workloadControl('paper-result-budget','Total results to retain',p.resultLimit||10)}<button id="reanalyze" ${busy(p)?'disabled':''}>Continue / retry unread passages</button><label>Evidence limitations (check against the source)<textarea id="paper-limitations">${esc(x.limitations||'Assessment pending.')}</textarea></label>${x.metrics.map((m,i)=>evidenceCard(p,x,m,i)).join('')||'<div class="notice">No supported results were retained. Inspect the coverage and rejection details, then retry missing passages or add source evidence.</div>'}<details><summary>Read retrieved source with line references</summary><button id="read-source">Load retrieved text</button><pre id="source-text" class="source-text"></pre></details><label>Review notes / reasons for a correction<textarea id="review-note" placeholder="Describe the source evidence supporting your decision.">${esc(x.reviewNote||'')}</textarea></label><label><input id="review-paper" type="checkbox" ${x.reviewed?'checked':''}> Include this reviewed paper in manuscript drafting</label>${info('review')}<div class="actions"><button class="primary" id="save-review" ${busy(p)?'disabled':''}>Save review and apply corrections</button><button id="add-detail">＋ Focus comparisons</button></div><details class="check-number" ${x.sourceRef?'open':''}><summary>Check a specific number from this paper</summary><p>Point Relay at any value you plan to compare against, for example a table cell. It locates the cell, reads the setup and appendices, and adds the number with its context.</p><div class="check-row"><input type="text" id="check-value" placeholder="Reported value" aria-label="Number as printed"><input type="text" id="check-method" placeholder="Model (optional)" aria-label="Model name"><button id="check-go" ${busy(p)?'disabled':''}>Check this number</button></div></details><details><summary>Enrich evidence from a paper or results table</summary><p>Paste a source excerpt including table headers, captions, and evaluation settings. It stays labeled as user-supplied evidence.</p><textarea id="excerpt" placeholder="Paste the experimental section or table here…"></textarea><button id="extract" ${busy(p)?'disabled':''}>Extract results with ${esc(p.model)}</button></details>`);
  bindWorkload('paper-result-budget');$('#read-source').onclick=async()=>{try{const source=await api('research/source?id='+encodeURIComponent(p.id)+'&paper='+encodeURIComponent(id));$('#source-text').textContent=source.text.split('\n').map((line,i)=>'L'+(i+1)+'  '+line).join('\n');$('#read-source').disabled=true}catch(e){toast(e.message)}};
  $('#save-review').onclick=async()=>{try{const r=await api('research/update',{id:p.id,revision:p.revision,action:'review',paper:id,reviewed:$('#review-paper').checked,verified:[...document.querySelectorAll('.verify:checked')].map(n=>+n.value),note:$('#review-note').value,topic:$('#paper-topic').value,rationale:$('#paper-rationale').value,limitations:$('#paper-limitations').value,metrics:x.metrics.map((m,i)=>Object.fromEntries([...document.querySelectorAll(`[data-edit-metric="${i}"]`)].map(n=>[n.dataset.field,n.value])))});$('#dialog').close();await refresh(true);if(r.corrections?.length){tab='corrections';routeTo();render();toast('Correction applied. Review its impact on comparisons and claims.')}else toast('Evidence review saved.')}catch(e){toast(e.message)}};
  $('#reanalyze').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'analyze',paper:id,resultLimit:workloadValue('paper-result-budget')});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}};$('#add-detail').onclick=()=>{selected.add(id);toast('Added to the comparison focus.')};$('#extract').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'evidence',paper:id,excerpt:$('#excerpt').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}};
  document.querySelectorAll('[data-investigate-metric]').forEach(b=>b.onclick=()=>investigate(p,[{paper:id,metric:b.dataset.investigateMetric}]));
  $('#check-go').onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'check',paper:id,value:$('#check-value').value.trim(),method:$('#check-method').value.trim()});$('#dialog').close();toast('Checking that number against the paper.');await refresh(true)}catch(e){toast(e.message)}}}

function investigate(p,targets,pair){
  const rows=targets.map(t=>({t,m:p.papers.find(x=>x.id===t.paper)?.metrics.find(m=>m.id===t.metric)})).filter(x=>x.m);
  const fields=[...new Set(rows.flatMap(({t,m})=>t.fields||m.missing||[]))].filter(f=>!['protocol','name'].includes(f));
  if(!fields.length){toast('No investigable field selected. Review the comparison criteria.');return}
  const label=f=>fieldLabel(f,rows[0]?.m);
  modal(`<div class="kicker">FOCUSED INVESTIGATION</div><h2>Resolve the blockers.</h2><p>${esc(p.model.includes('nemotron')?'Nemotron':p.model)} will inspect ${rows.length} selected result${rows.length===1?'':'s'}. Your other papers stay unchanged.</p><fieldset class="investigation-fields"><legend>Choose conditions to investigate</legend><button type="button" id="select-all-fields">Select all</button><button type="button" id="clear-fields">Clear selection</button>${fields.map((f,i)=>`<label><input type="checkbox" data-investigation-field="${esc(f)}" ${i<3?'checked':''}> ${esc(label(f))}</label>`).join('')}</fieldset><label>Your instructions <small>optional</small><textarea id="investigation-direction" maxlength="1500" placeholder="Check the original tables, source definitions, and study conditions. Explain which evidence applies to each observation. Keep unsupported fields unknown."></textarea></label><p class="hint">Paper evidence first, then author code and configured Tavily search. Findings become proposals for human review; instructions do not override source checks.</p><div class="actions"><button class="primary" id="start-focused-investigation">Start investigation</button><span id="investigation-error" role="status"></span></div>`);
  $('#select-all-fields').onclick=()=>document.querySelectorAll('[data-investigation-field]').forEach(x=>x.checked=true);$('#clear-fields').onclick=()=>document.querySelectorAll('[data-investigation-field]').forEach(x=>x.checked=false);
  $('#start-focused-investigation').onclick=async()=>{
    const chosen=[...document.querySelectorAll('[data-investigation-field]:checked')].map(x=>x.dataset.investigationField);
    if(!chosen.length){$('#investigation-error').textContent='Select at least one condition.';return}
    const button=$('#start-focused-investigation');button.disabled=true;
    try{await api('research/investigate',{id:p.id,revision:p.revision,targets:rows.map(({t})=>({...t,fields:chosen})),pair,repository:true,direction:$('#investigation-direction').value});$('#dialog').close();toast('Investigation running. Review its progress in Execution record.');await refresh(true)}catch(e){$('#investigation-error').textContent=e.message;button.disabled=false}
  };
}

function proposalsPanel(p){const pending=(p.proposals||[]).filter(x=>x.status==='pending');if(!pending.length)return '';return `<section class="proposals"><div class="section-title"><h3>Proposed corrections awaiting your review ${info('corrections')} <span class="badge">${pending.length}</span></h3><p>The agent found these in the sources. Nothing changes until you accept.</p></div>${pending.map(x=>`<article class="proposal"><div class="proposal-head"><span class="badge">${esc(x.origin==='repository'?'From authors’ code':x.origin==='web'?'From web search':'From the paper')}</span><strong>${esc(FIELD_LABELS[x.field]||x.field)} for ${esc(x.method)} ${esc(x.result)}</strong><small>${esc(x.paperTitle.slice(0,80))}</small></div><div class="proposal-change"><span class="before">${esc(x.current)}</span><span aria-hidden="true">→</span><input type="text" value="${esc(x.value)}" data-proposal-value="${x.id}" aria-label="Proposed value"></div><blockquote>${esc(x.quote)}</blockquote><p>${esc(x.explanation)}</p><small>${esc(x.location)} ${x.url?`· <a href="${esc(x.url)}" target="_blank" rel="noopener">open source ↗</a>`:''}</small><div class="actions"><button class="primary" data-accept="${x.id}" ${busy(p)?'disabled':''}>Accept and propagate</button><button data-reject="${x.id}" ${busy(p)?'disabled':''}>Reject</button></div></article>`).join('')}</section>`}
function bindProposals(p){document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{try{const r=await api('research/update',{id:p.id,revision:p.revision,action:'proposal',proposal:b.dataset.accept,decision:'accept',value:document.querySelector(`[data-proposal-value="${b.dataset.accept}"]`).value});await refresh(true);if(r.correction){tab='corrections';routeTo();render();toast('Correction applied. Here is what it changed.')}}catch(e){toast(e.message)}});document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'proposal',proposal:b.dataset.reject,decision:'reject'});await refresh(true);toast('Proposal rejected. The evidence is unchanged.')}catch(e){toast(e.message)}})}

function pairStatus(pair,field){const c=pair.checks.find(c=>c.field===field);return c?c.status:''}
function pairCard(p,pair){const [label]=OUTCOME[pair.outcome];const fields=pair.engine==='generic-v3'?[['method','Reported entity'],['entityId','Contract membership'],['name','Outcome / finding'],['value','Reported result'],['unit','Unit'],...factors(pair.a).map(f=>[f.key,f.label]),['locator','Source']]:[['method','Model'],['value','Reported value'],['dataset','Dataset'],['split','Split'],...(pair.a.protocol?.task&&pair.a.protocol.task!=='forecasting'?[]:[['horizon','Horizon']]),...visibleFactors(pair.a).map(f=>[f.key,f.label]),['aggregation','Aggregation'],['metricDefinition','Metric definition'],['provenance','Provenance'],['locator','Source']];const statusFor=f=>f==='aggregation'?pairStatus(pair,'horizon'):f==='value'?'':pairStatus(pair,f);
  const generic=pair.engine==='generic-v3';const fav=pair.favours?pair[pair.favours]:null;const gaps=[...new Set(pair.checks.filter(c=>['missing','conflict','caveat'].includes(c.status)).map(c=>c.field==='name'?null:c.field==='entity'?'entityId':c.field==='measurement'?'measurementQuote':c.field).filter(Boolean))].filter(f=>!['assessment','protocol','requirements','sourceReview'].includes(f));
  return `<article class="pair-card outcome-${pair.outcome}" id="pair-${pair.id}"><header><span class="outcome-badge">${label}</span><strong>${esc(pair.a.method)} ${esc(pair.a.name)} ${esc(pair.a.value)} <span class="vs">vs</span> ${esc(pair.b.method)} ${esc(pair.b.value)}</strong><span class="pair-meta">${generic?(pair.assessmentReviewed?'Human reviewed':pair.assessed?'Nemotron assessment · Ready for human review':'Awaiting assessment'):esc(pair.a.dataset)}${pair.verified?' · verified':' · not yet verified'}</span></header><div class="pair-grid" role="table"><div class="pg-row pg-head" role="row"><span role="columnheader">Context</span><span role="columnheader">${esc(pair.a.title.slice(0,70))}</span><span role="columnheader">${esc(pair.b.title.slice(0,70))}</span></div>${fields.map(([f,l])=>`<div class="pg-row st-${statusFor(f)}" role="row"><span role="rowheader">${esc(l)}</span><span role="cell">${esc(f==='entityId'?(pair.a.protocol.entities||[]).find(e=>e.id===pair.a.entityId)?.label||'Unresolved':pair.a[f])}</span><span role="cell">${esc(f==='entityId'?(pair.b.protocol.entities||[]).find(e=>e.id===pair.b.entityId)?.label||'Unresolved':pair.b[f])}</span></div>`).join('')}</div>${generic?`<details class="judgment-evidence"><summary>Inspect criterion judgments and evidence</summary>${pair.checks.map(c=>`<article><strong>${esc(c.label||c.field)} · ${esc(c.status)}</strong><p>${esc(c.detail)}</p>${(c.refs||[]).map(r=>`<blockquote>${esc(r.quote)}<small>${esc(r.id)} · source ${esc(r.source)}</small></blockquote>`).join('')}</article>`).join('')}</details>`:''}<ul class="pair-why">${pair.explanation.map(e=>`<li>${esc(e)}</li>`).join('')}${pair.caveats.map(c=>`<li class="caveat">Caveat: ${esc(c)}</li>`).join('')}${pair.independent?'':`<li class="caveat">${esc(pair.independence)}</li>`}</ul>${fav?`<p class="favours">${pair.verified?'Within this matched context, the':'Provisionally, the'} ${fav.direction==='higher'?'higher-scoring':'lower-error'} result is <b>${esc(fav.method)}</b> by ${esc(pair.delta)} (${esc(pair.relative)}%). This is a reported difference, not a significance test.</p>`:''}<div class="pair-actions">${generic&&pair.assessed?`<button data-retry-assessment="${pair.id}" ${busy(p)?'disabled':''}>Reassess this pair</button><button data-review-assessment="${pair.id}">${pair.assessmentReviewed?'Edit assessment review':'Review this assessment'}</button>`:''}${gaps.length?`<button class="primary" data-investigate-pair="${pair.id}" ${busy(p)?'disabled':''}>Investigate ${gaps.length} blocker${gaps.length===1?'':'s'} →</button>`:''}<button data-correct="${pair.id}">Correct a field</button><button data-detail="${pair.a.paper}">Inspect ${esc(pair.a.method)} ↗</button><button data-detail="${pair.b.paper}">Inspect ${esc(pair.b.method)} ↗</button></div></article>`}
async function compareView(p){const focus=[...selected].filter(id=>p.papers.some(x=>x.id===id));const generic=p.protocol?.version===3;const scope=methodScopes.get(p.id)||(!generic?p.protocol?.targetMethods:[])||[];const choices=generic?(p.protocol.entities||[]).map(e=>[e.id,e.label]):[...new Set(p.papers.flatMap(x=>x.metrics.map(m=>m.method)))].map(x=>[x,x]);$('#view').innerHTML=`${protocolPanel(p)}${(p.goalAssessments||[]).length?`<section class="coverage-panel"><span class="kicker">NEMOTRON · READY FOR HUMAN REVIEW</span><h3>Hypothesis judgments ${p.synthesisStale?'<span class="badge">Earlier assessment · evidence changed</span>':''}</h3>${p.goalAssessments.map(g=>`<article><strong>${esc(g.question)}</strong><p><span class="badge">${g.verdict==='inconclusive'?'Inconclusive':'Proposed '+esc(g.verdict)}</span> ${esc(g.explanation)}</p><small>${g.pairs.length} cited comparisons · not independently verified</small></article>`).join('')}</section>`:''}${coveragePanel(p)}${proposalsPanel(p)}<div class="toolbar"><div><h3>Does the comparison actually hold?</h3><small>${focus.length>=2?`Comparing ${focus.length} focused papers. `:'Proposing result pairs within the selected scope. '}Missing context gives “insufficient evidence”, never “incompatible”.</small></div><div><button id="choose">Focus papers</button> ${focus.length>=2?'<button id="clear-focus">Show all</button>':''}</div></div><section class="comparison-focus"><div><span class="kicker">01 / FOCUS THE QUESTION</span><h3>Which entities should be compared?</h3><p>Filter saved evidence instantly. No model call or re-extraction.</p></div><form id="method-scope"><label>First entity<select id="scope-left"><option value="">Choose an entity</option>${choices.map(([id,label])=>`<option value="${esc(id)}" ${scope[0]===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label><span aria-hidden="true">vs</span><label>Second entity<select id="scope-right"><option value="">Choose an entity</option>${choices.map(([id,label])=>`<option value="${esc(id)}" ${scope[1]===id?'selected':''}>${esc(label)}</option>`).join('')}</select></label><button type="submit">Apply focus</button><button type="button" id="scope-clear">All entities</button></form></section>${generic?`<section class="comparison-guidance"><span class="kicker">BOUNDED SEMANTIC ASSESSMENT</span><p>Choose how many pending pairs Nemotron should assess. Each call handles a small batch; larger selections continue across calls. Evidence changes invalidate earlier assessments.</p>${workloadControl('audit-budget','Comparisons to assess',p.comparisonLimit||12)}<button id="audit-comparisons" ${busy(p)?'disabled':''}>Assess pending comparisons</button></section>`:''}<div id="matched"><div class="empty">Checking experimental context…</div></div>`;bindProposals(p);bindCoverage();
  if($('#audit-budget'))bindWorkload('audit-budget');
  if($('#audit-comparisons'))$('#audit-comparisons').onclick=async()=>{try{await api('research/assess-comparisons',{id:p.id,revision:p.revision,entities:scope,limit:workloadValue('audit-budget')});toast('Nemotron is assessing pending comparisons.');await refresh(true)}catch(e){toast(e.message)}};
  $('#method-scope').onsubmit=e=>{e.preventDefault();const a=$('#scope-left').value.trim(),b=$('#scope-right').value.trim();if(!a||!b||a===b){toast('Enter two different entities, or choose All entities.');return}methodScopes.set(p.id,[a,b]);compareView(p)};$('#scope-clear').onclick=()=>{methodScopes.set(p.id,[]);compareView(p)};
  if($('#review-contract'))$('#review-contract').onclick=()=>{modal(`<h2>Review question coverage</h2><p>Check that every requirement in your question appears in the contract with the right role. This does not verify extracted results.</p><label>Review note<textarea id="contract-note"></textarea></label><button id="contract-approve">Mark coverage reviewed</button>`);$('#contract-approve').onclick=async()=>{try{await api('research/review-contract',{id:p.id,revision:p.revision,approved:true,note:$('#contract-note').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}}};
  if($('#revise-criteria'))$('#revise-criteria').onclick=()=>executions.branch(p,p.execution.at(-1).id,undefined,p.papers.length?'plan':'search');
  $('#choose').onclick=()=>{modal(`<h2>Focus on papers</h2>${p.papers.map(x=>`<label><input type="checkbox" data-select="${x.id}" ${selected.has(x.id)?'checked':''}> ${esc(x.title)}</label>`).join('')}<button class="primary" id="apply-selection">Compare selected papers</button>`);$('#apply-selection').onclick=()=>{selected=new Set([...document.querySelectorAll('[data-select]:checked')].map(x=>x.dataset.select));$('#dialog').close();compareView(p)}};if($('#clear-focus'))$('#clear-focus').onclick=()=>{selected.clear();compareView(p)};
  try{const key=p.id+':'+p.revision+':'+focus.join(',')+':'+JSON.stringify(scope);const r=comparisonCache.key===key?comparisonCache.data:await api('research/compare',{id:p.id,papers:focus,methods:scope});comparisonCache={key,data:r};if(!$('#matched'))return;
    if(r.requiresContract){$('#matched').innerHTML='<div class="notice"><strong>This saved evidence needs a comparison contract.</strong><p>The retired comparator is no longer run. Use Revise criteria in a branch → Re-extract evidence. Source records and prior checkpoints remain available.</p></div>';return}const s=r.summary;if(generic&&$('#audit-comparisons'))$('#audit-comparisons').textContent=`Assess pending comparisons (${s.pending})`;const show=r.pairs.filter(x=>(pairFilter==='all'||(pairFilter==='pending'?!x.assessed:x.assessed&&x.outcome===pairFilter))&&(!pairQuery||JSON.stringify([x.a.method,x.b.method,x.a.dataset,x.a.title,x.b.title]).toLowerCase().includes(pairQuery)));
    $('#matched').innerHTML=r.pairs.length?`<div class="comparison-guidance"><span class="kicker">02 / REVIEW THE EVIDENCE</span><p>${s.comparable?`${s.comparable} pair${s.comparable===1?' meets':'s meet'} the recorded criteria; this is not a verdict on the full hypothesis. Inspect the evidence before using a claim.`:'No pair currently meets all criteria. Review the blockers below; a missing condition is not proof that the experiments differ.'}</p><small>Existing evidence is checked with the current rules. Viewing this page makes no model call. Source values remain visible. Pairs are proposed for assessment, not ranked by scientific merit.</small></div><div class="outcome-summary">${['all','comparable','incompatible','insufficient','pending'].map(k=>`<button class="outcome-filter f-${k} ${pairFilter===k?'active':''}" data-filter="${k}"><b>${k==='all'?r.pairs.length:s[k]}</b>${k==='all'?'All pairs':OUTCOME[k][0]}<small>${k==='all'?`${s.assessed} assessed · ${s.pending} pending`:OUTCOME[k][1]}</small></button>`).join('')}</div><input type="search" id="pair-search" placeholder="Filter by entity or paper…" value="${esc(pairQuery)}" aria-label="Filter comparisons"><div class="pair-list">${show.slice(0,pairDisplayLimit).map(x=>pairCard(p,x)).join('')||'<div class="empty">No comparisons match this filter.</div>'}</div>${show.length>pairDisplayLimit?`<p>Showing ${pairDisplayLimit} of ${show.length} matching pairs.</p><button id="more-pairs">Show next 25</button> <button id="all-pairs">Show all ${show.length}</button>`:''}`:`<div class="empty">No result pairs match this entity focus. ${r.rows} results extracted. Check entity assignments, choose All entities, or inspect the evidence.</div>`;
    if($('#more-pairs'))$('#more-pairs').onclick=()=>{pairDisplayLimit+=25;compareView(p)};if($('#all-pairs'))$('#all-pairs').onclick=()=>{pairDisplayLimit=show.length;compareView(p)};
    document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{pairFilter=b.dataset.filter;pairDisplayLimit=25;compareView(p)});const search=$('#pair-search');if(search)search.oninput=()=>{pairQuery=search.value.toLowerCase();clearTimeout(search.t);search.t=setTimeout(()=>{compareView(p).then(()=>{const s=$('#pair-search');if(s){s.focus();s.setSelectionRange(s.value.length,s.value.length)}})},250)};
    document.querySelectorAll('[data-retry-assessment]').forEach(b=>b.onclick=async()=>{try{await api('research/assess-comparisons',{id:p.id,revision:p.revision,pair:b.dataset.retryAssessment});await refresh(true)}catch(e){toast(e.message)}});
    document.querySelectorAll('[data-review-assessment]').forEach(b=>b.onclick=()=>{const pair=r.pairs.find(x=>x.id===b.dataset.reviewAssessment);modal(`<h2>Review the assessment</h2><p>Check the criterion judgments and source applicability before recording your decision.</p><label>Review note<textarea id="assessment-note"></textarea></label><div class="actions"><button id="approve-assessment">Mark reviewed</button><button id="unapprove-assessment">Needs further review</button></div>`);for(const [id,approved] of [['approve-assessment',true],['unapprove-assessment',false]])$('#'+id).onclick=async()=>{try{await api('research/review-comparison',{id:p.id,revision:p.revision,pair:pair.id,approved,note:$('#assessment-note').value});$('#dialog').close();await refresh(true)}catch(e){toast(e.message)}}});
    document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>paperDetail(b.dataset.detail));
    document.querySelectorAll('[data-investigate-pair]').forEach(b=>b.onclick=()=>{const pair=r.pairs.find(x=>x.id===b.dataset.investigatePair);const fields=[...new Set(pair.checks.filter(c=>['missing','conflict','caveat'].includes(c.status)&&!['name','assessment','protocol','requirements','sourceReview'].includes(c.field)).map(c=>c.field==='horizon'?['horizon','aggregation']:[c.field==='entity'?'entityId':c.field==='measurement'?'measurementQuote':c.field]).flat())];investigate(p,[{paper:pair.a.paper,metric:pair.a.metric,fields},{paper:pair.b.paper,metric:pair.b.metric,fields}],pair.id)});
    document.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>correctDialog(p,r.pairs.find(x=>x.id===b.dataset.correct)))}catch(e){toast(e.message)}}
function correctDialog(p,pair){modal(`<div class="kicker">RESEARCHER CORRECTION</div><h2>Correct the experimental context.</h2><p>Your correction is recorded with your reason. Relay recomputes every affected comparison, marks dependent manuscript claims stale, and keeps the previous state as a checkpoint you can branch from.</p><label>Result<select id="fix-side"><option value="a">${esc(pair.a.method)} ${esc(pair.a.value)} · ${esc(pair.a.title.slice(0,60))}</option><option value="b">${esc(pair.b.method)} ${esc(pair.b.value)} · ${esc(pair.b.title.slice(0,60))}</option></select></label><label>Field<select id="fix-field">${contextFields(pair.a).filter(f=>f!=='locator'&&f!=='citedFrom').map(f=>`<option value="${f}">${esc(fieldLabel(f,pair.a))}</option>`).join('')}</select></label><p id="fix-current" class="hint"></p><label>Correct value<input type="text" id="fix-value"></label><label>Why is this correct? <small>(table, appendix, code line, or author statement)</small><textarea id="fix-note" placeholder="The paper text says 70/20/10 but its data script uses 70/10/20."></textarea></label><button class="primary" id="fix-go">Apply correction</button>`);
  const show=()=>{const r=pair[$('#fix-side').value],f=$('#fix-field').value;$('#fix-current').textContent='Current value: '+r[f];$('#fix-value').value=known(r[f])?r[f]:''};$('#fix-side').onchange=show;$('#fix-field').onchange=show;show();
  $('#fix-go').onclick=async()=>{const r=pair[$('#fix-side').value];try{await api('research/update',{id:p.id,revision:p.revision,action:'correct',paper:r.paper,metric:r.metric,field:$('#fix-field').value,value:$('#fix-value').value,note:$('#fix-note').value});$('#dialog').close();await refresh(true);tab='corrections';routeTo();render();toast('Correction applied. Here is what it changed.')}catch(e){toast(e.message)}}}

function correctionsView(p){const list=p.corrections||[];$('#view').innerHTML=`${proposalsPanel(p)}<div class="toolbar"><div><h3>What changed when the evidence changed</h3><small>Each correction recomputes comparisons, marks dependent claims stale, and keeps the earlier state as a checkpoint.</small></div>${(p.draft&&['relatedWork','comparisons'].some(s=>(p.draft[s]||[]).some(i=>i.stale)))?`<button class="primary" id="regen" ${busy(p)?'disabled':''}>Regenerate stale claims</button>`:''}</div>${list.length?`<div class="correction-list">${list.map(c=>`<article class="correction status-${esc(c.status)}"><header><span class="badge">${esc({stale:'Claims need regeneration','affects-comparisons':'Comparisons changed','no-dependents':'No dependent results',regenerated:'Claims regenerated',reviewed:'Reviewed'}[c.status]||c.status)}</span><strong>${esc(c.result)}</strong><small>${esc(c.paperTitle.slice(0,80))} · ${esc(c.origin)} · ${esc(c.at.slice(0,16).replace('T',' '))}</small></header><div class="change-list">${c.changes.map(ch=>`<div><span>${esc(FIELD_LABELS[ch.field]||ch.field)}</span><span class="before">${esc(ch.before)}</span><span aria-hidden="true">→</span><span class="after">${esc(ch.after)}</span></div>`).join('')}</div>${c.note?`<p class="note">${esc(c.note)}</p>`:''}<h4>Comparisons affected <span class="badge">${c.comparisonChanges.length}</span></h4>${c.comparisonChanges.length?`<ul class="impact">${c.comparisonChanges.map(x=>`<li>${x.before===x.after?`<span class="o-${esc(x.after)}">Still ${esc((OUTCOME[x.after]?.[0]||x.after).toLowerCase())}</span> · reason updated`:`<span class="o-${esc(x.before)}">${esc(OUTCOME[x.before]?.[0]||x.before)}</span> → <span class="o-${esc(x.after)}">${esc(OUTCOME[x.after]?.[0]||x.after)}</span>`} <b>${esc(x.label)}</b><br><small>${esc((x.explanation||[]).join(' '))}</small></li>`).join('')}</ul>`:'<p class="hint">No comparison outcome changed.</p>'}<h4>Manuscript claims marked stale <span class="badge">${c.staleClaims.length}</span></h4>${c.staleClaims.length?`<ul class="impact">${c.staleClaims.map(s=>`<li><b>${esc(s.section==='comparisons'?'Evidence assessment':'Related work')}</b> “${esc(s.excerpt)}…”<br><small>${esc(s.reason)}</small></li>`).join('')}</ul>`:'<p class="hint">No drafted claim depended on this result.</p>'}<div class="actions"><button data-branch-before="${c.beforeNode||''}" ${!c.beforeNode?'disabled title="Historical checkpoint unavailable in imported snapshot"':''} data-label="${esc(c.result.slice(0,50))}">⑂ Open the state before this correction</button>${c.status!=='reviewed'?`<button data-resolve="${c.id}" ${busy(p)?'disabled':''}>Mark impact reviewed</button>`:''}</div></article>`).join('')}</div>`:'<div class="empty">No corrections yet. Accept an agent proposal or correct a field from the comparisons view; its consequences appear here.</div>'}`;
  bindProposals(p);if($('#regen'))$('#regen').onclick=async()=>{try{await api('research/regenerate',{id:p.id,revision:p.revision});toast('Regenerating the affected claims.');await refresh(true)}catch(e){toast(e.message)}};
  document.querySelectorAll('[data-branch-before]').forEach(b=>b.onclick=async()=>{try{const r=await api('research/branch',{id:p.id,node:b.dataset.branchBefore,next:'snapshot',name:'Before correction: '+b.dataset.label});await refresh(true);openProject(r.id,'compare');toast('Opened an independent branch with the earlier evidence.')}catch(e){toast(e.message)}});
  document.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{try{await api('research/update',{id:p.id,revision:p.revision,action:'resolve',correction:b.dataset.resolve});await refresh(true)}catch(e){toast(e.message)}})}

const CLAIM={supported:['Supported','Backed by a verified comparable comparison'],provisional:['Provisional','Comparable, but values are not yet verified'],attributed:['Attributed','Reports what a paper claims'],descriptive:['Descriptive','No performance claim'],unsupported:['Review claim','Automatic wording check flagged this paragraph; inspect meaning and comparison support. Cautious or negated statements may also be flagged.']};
function paragraphHTML(i){const c=CLAIM[i.claim]||['',''];return `<div class="draft-paragraph ${i.stale?'stale':''}">${i.stale?`<div class="stale-flag">Stale: ${esc(i.staleReason)}</div>`:''}<p>${esc(i.text)} <small>[${esc((i.citations||[]).join(', '))}]</small> ${i.claim?`<span class="claim claim-${esc(i.claim)}" title="${esc(c[1])}">${esc(c[0])}</span>`:''}</p>${i.previous?`<details><summary>Previous text (before regeneration)</summary><p class="previous">${esc(i.previous)}</p></details>`:''}</div>`}
function writeView(p){const d=p.draft,staleN=d?['relatedWork','comparisons'].reduce((n,s)=>n+(d[s]||[]).filter(i=>i.stale).length,0):0,unsupported=d?['relatedWork','comparisons'].reduce((n,s)=>n+(d[s]||[]).filter(i=>i.claim==='unsupported').length,0):0;
  $('#view').innerHTML=`<div class="editor-tools"><button class="primary" id="draft" ${busy(p)?'disabled':''}>${p.tex?'Rewrite with feedback':'Generate reviewed draft'}</button>${staleN?`<button class="accent" id="regen-write" ${busy(p)?'disabled':''}>Regenerate ${staleN} stale claim${staleN>1?'s':''}</button>`:''}<button id="save-tex">Save edits</button><button id="compile" ${!p.tex?'disabled':''}>Compile PDF</button><a href="/api/research/export/${p.id}" download="relay-research.zip">Export Overleaf ZIP ↗</a><span class="review-count">${p.papers.filter(x=>x.reviewed).length} reviewed papers</span></div>${staleN?`<div class="notice warn">${staleN} paragraph${staleN>1?'s depend':' depends'} on evidence that changed. Regenerate after reviewing the corrections, or edit by hand.</div>`:''}${unsupported?`<div class="notice error">${unsupported} paragraph${unsupported>1?'s need':' needs'} claim review. Automatic wording checks can also flag cautious or negated statements. Inspect citations and comparison support before approving.</div>`:''}<div class="notice">The manuscript proposes a study. It includes the comparison outcomes and the experimental controls they imply. No experiment for your question has been run.</div><div class="editor-layout"><div class="editor"><div class="editor-bar"><select id="editor-file" aria-label="Manuscript file" style="width:175px"><option value="tex" ${editorFile==='tex'?'selected':''}>main.tex</option><option value="bib" ${editorFile==='bib'?'selected':''}>references.bib</option></select><span id="save-state">Saved locally · revision ${p.revision}</span></div><textarea id="code" aria-label="LaTeX source" spellcheck="false">${esc(p[editorFile]||'')}</textarea></div><div class="editor"><div class="editor-bar"><span id="preview-label">${p.compile?.ok?'Last compiled PDF':'Claims and evidence'}</span><span>${p.compile?.ok?'<button id="show-claims">Show claims</button>':''} <label><input type="checkbox" id="draft-reviewed" ${p.draftReviewed?'checked':''}> Human reviewed</label></span></div><div id="preview">${p.compile?.ok&&!staleN?`<iframe title="Compiled manuscript PDF" src="/api/research/pdf/${p.id}/${p.compile.hash}"></iframe>`:claimsPreview(p)}</div></div></div><details><summary>Compilation log & export notes</summary><pre class="logs" id="compile-log">${esc(p.compile?.log||'No compilation yet.')}</pre><p>Import the ZIP as a new Overleaf project. It includes main.tex, references.bib, and the evidence record with every correction. This app does not edit an existing Overleaf account.</p></details>`;
  $('#code').oninput=()=>{dirty=true;$('#save-state').textContent='Unsaved edits';$('#draft-reviewed').checked=false};$('#draft-reviewed').onchange=()=>{dirty=true;$('#save-state').textContent='Unsaved review'};$('#editor-file').onchange=async()=>{const next=$('#editor-file').value;if(dirty)try{await saveEditor()}catch(e){toast(e.message);$('#editor-file').value=editorFile;return}editorFile=next;writeView(current())};$('#save-tex').onclick=async()=>{try{await saveEditor();toast('Manuscript saved.')}catch(e){toast(e.message)}};$('#draft').onclick=()=>draftDialog(p);if($('#show-claims'))$('#show-claims').onclick=()=>{$('#preview').innerHTML=claimsPreview(p);$('#preview-label').textContent='Claims and evidence'};
  if($('#regen-write'))$('#regen-write').onclick=async()=>{try{if(dirty)await saveEditor();const latest=current();await api('research/regenerate',{id:latest.id,revision:latest.revision});toast('Regenerating the affected claims.');await refresh(true)}catch(e){toast(e.message)}};
  $('#compile').onclick=async()=>{const b=$('#compile');b.disabled=true;b.textContent='Compiling…';try{await saveEditor();const latest=current();const r=await api('research/compile',{id:latest.id,revision:latest.revision});$('#compile-log').textContent=r.log;if(r.ok){$('#preview').innerHTML=`<iframe title="Compiled manuscript PDF" src="${esc(r.url)}"></iframe>`;$('#preview-label').textContent='Compiled PDF';toast('PDF compiled successfully.')}else toast('LaTeX compilation failed. Open the log for details.');await refresh()}catch(e){toast(e.message)}finally{if($('#compile')){$('#compile').disabled=false;$('#compile').textContent='Compile PDF'}}}}
function claimsPreview(p){const d=p.draft;if(!d)return '<div class="preview"><h3>Your next draft starts with evidence.</h3><p>Review papers in the Evidence step and include the ones you checked. The agent drafts related work, an evidence assessment built from the comparison outcomes, and the next defensible experiment.</p></div>';return `<div class="preview"><h3>Abstract ${d.summaryStale?'<span class="claim claim-unsupported">Review after corrections</span>':''}</h3><p>${esc(d.abstract)}</p><h3>Related work</h3>${(d.relatedWork||[]).map(paragraphHTML).join('')}<h3>Evidence assessment</h3>${(d.comparisons||[]).map(paragraphHTML).join('')||'<p>No comparison paragraphs.</p>'}${(d.pairTable||[]).length?`<table class="mini-table"><thead><tr><th>Result A</th><th>Result B</th><th>Outcome</th></tr></thead><tbody>${d.pairTable.map(r=>`<tr><td>${esc(r.a)}</td><td>${esc(r.b)}</td><td><span class="o-${esc(r.outcome)}">${esc(OUTCOME[r.outcome]?.[0]||r.outcome)}</span></td></tr>`).join('')}</tbody></table>`:''}<h3>Proposed study</h3><p class="prewrap">${esc(d.study)}</p>${(d.controls||[]).length?`<h3>Controls required by the evidence</h3><ul>${d.controls.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ul>`:''}</div>`}
async function saveEditor(){const p=current();const tex=editorFile==='tex'?$('#code').value:p.tex,bib=editorFile==='bib'?$('#code').value:p.bib;await api('research/update',{id:p.id,revision:p.revision,action:'save',tex,bib,reviewed:$('#draft-reviewed').checked});dirty=false;await refresh();}
function draftDialog(p){modal(`<div class="kicker">HUMAN IN THE LOOP</div><h2>Shape the argument before it is written.</h2><p>The agent will use ${p.papers.filter(x=>x.reviewed).length} reviewed papers and their comparison outcomes. It may only claim one method is better when the comparison holds; otherwise it must explain why the numbers cannot be compared.</p><label>Your direction, corrections, or exclusions<textarea id="feedback" placeholder="Focus on which baselines I can re-run under one protocol. Do not claim we have run experiments.">${esc(p.feedback||'')}</textarea></label><p>A new draft replaces the editor contents. The previous version stays in the execution record.</p><button class="primary" id="generate" ${!p.papers.some(x=>x.reviewed)?'disabled':''}>Generate proposed-study draft</button>`);$('#generate').onclick=async()=>{try{if(dirty)await saveEditor();const latest=current();await api('research/draft',{id:latest.id,revision:latest.revision,feedback:$('#feedback').value});$('#dialog').close();dirty=false;await refresh(true)}catch(e){toast(e.message)}}}

const TRACE_KIND={plan:'Planning the search',assess:'Judging how well a paper fits',extract:'Extracting reported results',['extract-retry']:'Retrying extraction from the table rows',['draft']:'Drafting the manuscript',['draft-repair']:'Repairing the draft',synthesis:'Writing research directions',investigate:'Investigating a missing detail',regenerate:'Regenerating stale claims',target:'Checking one number',reassess:'Reassessing a paper',baseline:'Comparing a baseline'};
function agentTrace(p){const steps=[...(p.events||[]).map(e=>({t:Date.parse(e.time)||0,text:e.message,kind:'event'})),...(p.calls||[]).map(c=>({t:Date.parse(c.at)||0,text:TRACE_KIND[c.kind]||c.kind,kind:'model',ms:c.ms||0,tokens:c.totalTokens||0,ok:c.ok!==false,attempts:c.attempts||1}))].sort((a,b)=>a.t-b.t);
  if(!steps.length)return '';const t0=steps[0].t,calls=steps.filter(s=>s.kind==='model'),tokens=calls.reduce((n,c)=>n+c.tokens,0),modelS=calls.reduce((n,c)=>n+c.ms,0)/1000,failed=calls.filter(c=>!c.ok).length;
  const shown=steps.slice(-60);
  return `<section class="agent-trace" aria-label="Agent trace"><div class="trace-head"><div><div class="kicker">AGENT TRACE</div><h3>What the agent did</h3></div><div class="trace-totals"><span><b>${calls.length}</b> model calls</span><span><b>${modelS.toFixed(1)} s</b> model time</span><span><b>${tokens.toLocaleString()}</b> tokens</span>${failed?`<span class="bad"><b>${failed}</b> failed</span>`:''}</div></div><p class="trace-model">${esc(p.model)} via ${esc(p.provider==='nebius'?'Nebius Token Factory':'Ollama Cloud')}</p><ol class="trace-list">${shown.map(s=>`<li class="trace-row ${s.kind}${s.kind==='model'&&!s.ok?' failed':''}"><span class="trace-time">+${((s.t-t0)/1000).toFixed(1)}s</span><span class="trace-dot" aria-hidden="true"></span><span class="trace-text">${esc(s.text)}${s.kind==='model'?`<small> · ${(s.ms/1000).toFixed(1)} s · ${s.tokens.toLocaleString()} tokens${s.attempts>1?' · retried':''}${s.ok?'':' · failed'}</small>`:''}</span></li>`).join('')}</ol>${steps.length>shown.length?`<p class="hint">Showing the last ${shown.length} of ${steps.length} steps.</p>`:''}</section>`}
function executionView(p){executions.graph(p);$('#view').insertAdjacentHTML('afterbegin',agentTrace(p));const calls=p.calls||[];if(!calls.length)return;const ok=calls.filter(c=>c.ok).length,tokens=calls.reduce((n,c)=>n+c.totalTokens,0),ms=calls.reduce((n,c)=>n+(c.ms||0),0),retried=calls.filter(c=>c.attempts>1||c.repaired).length;
  $('#view').insertAdjacentHTML('beforeend',`<section class="side-card calls"><h3>Model calls ${info('calls')} <span class="badge">${calls.length}</span></h3><p>${ok} succeeded · ${calls.length-ok} failed · ${retried} recovered by retry or JSON repair · ${tokens.toLocaleString()} tokens · ${(ms/1000).toFixed(1)} s of model time. Every call records its model, latency, and token use.</p><div class="table-wrap"><table><thead><tr><th>Step</th><th>Model</th><th>Time</th><th>Tokens</th><th>Attempts</th><th>Result</th></tr></thead><tbody>${calls.slice(-40).reverse().map(c=>`<tr><td>${esc(c.kind)}</td><td>${esc(c.model)}</td><td>${((c.ms||0)/1000).toFixed(1)} s</td><td>${(c.totalTokens||0).toLocaleString()}</td><td>${c.attempts}${c.repaired?' · JSON repaired':''}${c.retries?' · '+esc(c.retries.join(', ')):''}</td><td>${c.ok?'OK':esc(c.error||'failed')}</td></tr>`).join('')}</tbody></table></div></section>`)}

$('#model-button').onclick=()=>{modal(`<div class="kicker">RESEARCH AGENT</div><h2>Choose your model. ${info('model')}</h2><p>Models are fetched live from your configured provider. Existing investigations keep the model they started with.</p><label>Provider<select id="provider"><option value="nebius" ${provider==='nebius'?'selected':''}>Nebius Token Factory</option><option value="ollama" ${provider==='ollama'?'selected':''}>Ollama Cloud</option></select></label><label>Your API key <small>(this browser tab only; the server uses it for your requests and never saves it)</small><input type="password" id="api-key" autocomplete="off" placeholder="Paste your key" value="${esc(keyFor(provider))}"></label><label>Tavily key (optional: discovery and focused evidence search)<input type="password" id="tavily-key" autocomplete="off" placeholder="Paste your key" value="${esc(keyFor('tavily'))}"></label><label>Model<select id="models"><option>Loading live catalog…</option></select></label><p id="model-info"></p><button class="primary" id="use-model" disabled>Use selected model</button>`);let generation=0;async function load(){const n=++generation;$('#use-model').disabled=true;try{const r=await api('models?provider='+$('#provider').value);if(n!==generation||!$('#models'))return;const want=$('#provider').value===provider&&model?model:r.default;$('#models').innerHTML=r.models.map(m=>`<option ${m===want?'selected':''}>${esc(m)}</option>`).join('');$('#model-info').textContent=r.models.length+' available models · credentials stay on the local companion';$('#use-model').disabled=!r.models.length}catch(e){if($('#model-info'))$('#model-info').textContent=e.message}}$('#provider').onchange=load;load();$('#api-key').oninput=()=>{const k=cleanKey($('#api-key').value);if(k)sessionStorage.setItem('relay-key-'+$('#provider').value,k);clearTimeout(load.t);load.t=setTimeout(load,400)};$('#tavily-key').oninput=()=>{const k=cleanKey($('#tavily-key').value);if(k)sessionStorage.setItem('relay-key-tavily',k);else sessionStorage.removeItem('relay-key-tavily')};$('#use-model').onclick=()=>{provider=$('#provider').value;model=$('#models').value;const k=cleanKey($('#api-key').value);if(k)sessionStorage.setItem('relay-key-'+provider,k);localStorage.setItem('relay-provider',provider);localStorage.setItem('relay-model',model);$('#dialog').close();sidebar();toast('Model selected for new investigations.')}};
const desk=researchDesk({$,esc,api,toast,modal,openProject,openPaper:async(id,arxiv)=>{await openProject(id,'papers');const paper=current()?.papers.find(p=>p.arxiv===arxiv);if(paper)paperDetail(paper.id)},newStudy:newInvestigation});
const executions=executionUI({$,esc,api,modal,toast,getProjects:()=>projects,getCurrent:current,openProject,openTab,refresh});
if(initialRoute.get('node'))executions.setNode(initialRoute.get('node'));
// ---- Browser copies: local list, restore, autosave, and the "Your projects" panel ----
const local={ready:true,copies:[],tried:new Set(),errors:new Map(),status:new Map(),saved:new Map(),saving:new Set(),retryAt:new Map(),restored:false,down:false,warnedSave:false};
const isNetworkError=e=>e instanceof TypeError;
const idOK=id=>/^[a-f0-9]{16}$/.test(String(id||''));
const copyOf=id=>local.copies.some(c=>c.id===id);
function idsParam(extra=[]){return [...new Set([...local.copies.map(c=>c.id),active,...extra].filter(idOK))].join(',')}
async function loadProjects(extra=[]){const s=await api('research?ids='+encodeURIComponent(idsParam(extra)));projects=s.projects;return s}
async function saveCopy(id,{auto=false}={}){
  if(!local.ready||!idOK(id)||local.saving.has(id))return false;
  if(auto&&Date.now()<(local.retryAt.get(id)||0))return false;
  local.saving.add(id);
  try{
    const doc=await api('research/project?id='+id);
    if(!LP.mayKeepCopy(doc.project,removed)){local.saving.delete(id);return false}
    const ok=await store.saveProject(doc);
    if(ok){local.copies=[{id,hypothesis:doc.project.hypothesis,savedAt:new Date().toISOString()},...local.copies.filter(c=>c.id!==id)];local.saved.set(id,doc.project.revision+':'+doc.project.status)}
    else{local.retryAt.set(id,Date.now()+30000);if(!local.warnedSave){local.warnedSave=true;toast('This browser could not keep a copy of the project. Export a file to keep it.')}}
    return ok;
  }catch(e){local.retryAt.set(id,Date.now()+30000);return false}
  finally{local.saving.delete(id)}
}
// Saves when a project first appears, when a run finishes, or when it reaches review.
function syncCopies(){
  for(const p of projects){
    const prev=local.status.get(p.id);local.status.set(p.id,p.status);
    const finished=prev!==undefined&&BUSY.includes(prev)&&!busy(p);
    const reviewed=prev!==undefined&&prev!==p.status&&p.status==='review';
    if(!copyOf(p.id)||finished||reviewed)saveCopy(p.id,{auto:true});
  }
}
// Every 60 seconds, save open-able projects that are not busy and changed since the last save.
function autosaveTick(){for(const p of projects)if(!busy(p)&&local.saved.get(p.id)!==p.revision+':'+p.status)saveCopy(p.id,{auto:true})}
// Projects in this browser that the server does not know (for example after a restart) are sent back once.
async function restoreMissing(){
  const have=new Set(projects.map(p=>p.id));
  for(const id of have){local.tried.delete(id);local.errors.delete(id)}
  const missing=local.copies.map(c=>c.id).filter(id=>!have.has(id)&&!local.tried.has(id)&&!removed.has(id));
  let restored=false;
  for(const id of missing){
    const doc=await store.getProject(id);
    if(!doc){local.tried.add(id);local.errors.set(id,'This copy could not be read from this browser.');continue}
    try{
      const r=await api('research/import',doc);
      local.tried.add(id);restored=true;
      if(r.existing)toast('This project is already in Relay, so nothing was replaced.');else local.restored=true;
    }catch(e){
      if(isNetworkError(e))return;
      local.tried.add(id);local.errors.set(id,e.message);
    }
  }
  if(restored)await loadProjects();
}
$('#projects-panel').onclick=()=>projectsPanel();
const panelMsg=t=>{const m=$('#panel-msg');if(m)m.textContent=t};
const when=iso=>{const d=new Date(iso);return isNaN(d)?'':d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'})};
const fmtBytes=n=>n>=1e6?(n/1e6).toFixed(1)+' MB':Math.round(n/1e3)+' KB';
const slug=s=>String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,60).replace(/-+$/,'')||'investigation';
function checkCopy(text,size){return LP.checkFile(text,size)}
async function exportCopy(id){
  let doc;
  try{doc=await api('research/project?id='+id)}catch(e){doc=await store.getProject(id);if(!doc)throw e}
  const name=slug(doc.project.hypothesis)+'.relay-research.json';
  const url=URL.createObjectURL(new Blob([JSON.stringify(doc,null,2)],{type:'application/json'}));
  const a=Object.assign(document.createElement('a'),{href:url,download:name});document.body.append(a);a.click();a.remove();
  setTimeout(()=>URL.revokeObjectURL(url),2000);
  panelMsg('Exported '+name+'.');
}
async function dropSampleCopies(){
  // Starter investigations are never the user's: remove any browser copy saved by an earlier version.
  const sampleIds=new Set([...samples.map(s=>s.id),...projects.filter(LP.isSample).map(p=>p.id)]);
  for(const c of local.copies.filter(c=>sampleIds.has(c.id))){await store.deleteProject(c.id);local.copies=local.copies.filter(x=>x.id!==c.id);local.saved.delete(c.id)}
}
function renderSamples(){
  const box=$('#samples');if(!box)return;
  const open=localStorage.getItem('relay-samples-open')==='1';
  const shown=[...new Map(samples.map(s=>[s.studyKey||s.id,s])).values()];
  box.innerHTML=`<details class="sample-section" id="samples-details" ${open?'open':''}><summary><span>Sample investigations</span><small>starter examples · start your own copy to change them</small></summary>${shown.length?shown.map(s=>`<div class="sample-row"><button class="project-link" data-project="${s.id}">${esc((s.branchName||s.hypothesis).slice(0,90))}<small>${s.papers} papers · ${esc(s.status)} · sample</small></button><button class="sample-copy" data-copy-sample="${s.id}">Start my own copy</button></div>`).join(''):'<p class="side-note">Samples appear here after the Research desk loads them.</p>'}</details>`;
  $('#samples-details').addEventListener('toggle',e=>localStorage.setItem('relay-samples-open',e.target.open?'1':'0'));
  box.querySelectorAll('[data-copy-sample]').forEach(b=>b.onclick=()=>startFromSample(b.dataset.copySample));
}
async function startFromSample(id){
  const sample=samples.find(x=>x.id===id);
  if(!sample)return toast('This sample is not available. Open the Research desk to load it.');
  try{
    const r=await api('research/branch',LP.copyFromSampleBody(sample));
    await saveCopy(r.id);await loadProjects([r.id]);
    active=r.id;screen='project';tab='compare';localStorage.setItem('research-project',active);routeTo();render();sidebar();
    toast('Your copy is ready. Changes stay in this browser.');
  }catch(e){toast(e.message)}
}
async function removeCopy(id){
  if(!confirm('Remove this copy from this browser? Files you exported are not affected. The server copy is removed when the server restarts.'))return;
  removed=LP.markRemoved(localStorage,id);projects=projects.filter(p=>p.id!==id);
  await store.deleteProject(id);
  local.copies=local.copies.filter(c=>c.id!==id);local.tried.delete(id);local.errors.delete(id);local.saved.delete(id);local.status.delete(id);
  if(active===id){active=null;localStorage.removeItem('research-project');screen='project';routeTo();render()}
  sidebar();projectsPanel('Removed from this browser.');
}
async function importFile(file){
  panelMsg('Checking the file…');
  try{
    const doc=checkCopy(await file.text(),file.size);
    const id=doc.project.id;
    const r=await api('research/import',doc);
    removed=LP.unmarkRemoved(localStorage,id);
    await saveCopy(id);
    await loadProjects([id]);
    $('#dialog').close();
    toast(r.existing?'This project is already in Relay, so nothing was replaced. Opening it.':'Project imported. Opening it.');
    await openProject(id,'compare');
  }catch(e){panelMsg(e.message)}
}
function panelHTML(msg=''){
  const rows=[...local.copies].map(c=>`<article class="copy-row"><div><strong>${esc(c.hypothesis.slice(0,160))}</strong><small>Saved ${esc(when(c.savedAt))}${local.errors.has(c.id)?' · Could not be restored: '+esc(local.errors.get(c.id)):''}</small></div><div class="copy-actions"><button data-export="${esc(c.id)}">Export file</button><button data-remove="${esc(c.id)}">Remove from this browser</button></div></article>`).join('');
  return `<div class="kicker">YOUR PROJECTS</div><h2>Your projects stay in this browser. ${info('projects')}</h2><p>Saved in this browser only. No account needed. Export a file to keep a backup or move to another computer.</p>${local.ready?'':'<p class="side-note warn">This browser window cannot keep copies, so projects are lost when you close it. Export a file to keep one.</p>'}<p class="storage-note" id="storage-note">Checking storage…</p><div class="copy-list">${rows||`<p class="empty-copy">${local.ready?'Start an investigation. It is saved in this browser.':'Start an investigation. This browser window cannot keep it after you close the window.'}</p>`}</div><h3>Open a file</h3><p>Import a file you exported earlier (.relay-research.json). A project that already exists is never replaced.</p><input type="file" id="import-file" accept=".relay-research.json,application/json"><p class="panel-msg" id="panel-msg" role="status">${esc(msg)}</p>`;
}
async function projectsPanel(msg=''){
  modal(panelHTML(msg));
  document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportCopy(b.dataset.export).catch(e=>panelMsg(e.message)));
  document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeCopy(b.dataset.remove));
  $('#import-file').onchange=()=>{const f=$('#import-file').files[0];if(f)importFile(f)};
  const el=$('#storage-note');
  if(!local.ready){el.textContent='Nothing is kept in this browser window.';return}
  const e=await store.estimateStorage();
  if($('#storage-note'))$('#storage-note').textContent=e?`${fmtBytes(e.usage)} used by Relay in this browser`:'Storage use is not reported by this browser.';
}

local.ready=await store.isAvailable();if(!local.ready)toast('This browser window cannot keep copies of your projects. They are lost when you close it unless you export a file.');local.copies=local.ready?await store.listProjects():[];
try{const boot=await api('state');token=boot.token;serverKeys=boot.providers||{};hostedMode=!!boot.hosted;if(!provider){provider=(boot.providers?.nebius||boot.hosted)?'nebius':'ollama';model=provider==='nebius'?boot.model:'gpt-oss:120b'}await refresh(true)}catch(e){if(isNetworkError(e)){local.down=true;sidebar()}else toast(e.message)}setInterval(()=>refresh(),2200);setInterval(autosaveTick,60000);
